/* AppArchive02Mapper.selectArchiveTypeList */
SELECT
    D.BAIM_VAL_D_CD     AS archiveTypeCd
  , D.BAIM_VAL_D_NM     AS archiveTypeNm
  , D.SORT_IDX          AS sortIdx
FROM TB_BAIM_VAL_D D
WHERE D.CMPNY_CD = #{gvCmpnyCd}
  AND D.BAIM_VAL_CD = #{baimValCd}
  AND D.USE_YN = 'Y'
ORDER BY D.SORT_IDX ASC, D.BAIM_VAL_D_CD ASC

/* AppArchive02Mapper.countArchiveTypeValid */
SELECT
    COUNT(1)
FROM TB_BAIM_VAL_D D
WHERE D.CMPNY_CD = #{cmpnyCd}
  AND D.BAIM_VAL_CD = #{baimValCd}
  AND D.BAIM_VAL_D_CD = #{archiveTypeCd}

    AND D.USE_YN = 'Y'

/* AppArchive02Mapper.countArchiveVisible */
SELECT
    COUNT(1)
FROM TB_NOTICE N
WHERE N.CMPNY_CD = #{gvCmpnyCd}
  AND N.NOTICE_ID = #{noticeId}
  AND N.NOTICE_TYPE = 'ARCHIVE'
  AND N.DEL_YN = 'N'

