/* AppArchive02Mapper.countNodeAdminAnySite */
SELECT
    COUNT(1)
FROM TB_SITE_NODE
WHERE CMPNY_CD = #{cmpnyCd}
  AND ( MAIN_ADMIN_CD = #{userCd} OR SUB_ADMIN_CD = #{userCd} )
